# --- gameworld environment hook -------------------------------------------
# Projects run state to the page as window.__pigeonHook(state) for game_api.js.
# `?start=run` deletes the local save DB (Hall of Tries/achievements) and presses
# the title FIGHT button's own startGame(), so the page opens on a fresh level-1 hub.
const _GW_BATTLE := "res://scenes/battleSceneNew.tscn"
const _GW_OPPONENTS := "res://scenes/opponentPanelControl.tscn"
const _GW_EVOLVE := "res://scenes/evolvePannel.tscn"
var _gwWeb := false
var _gwStartRun := false
var _gwStarted := false
var _gwT := 0.0
var _gwMaxLevel := 1
var _gwRunsStarted := 0
var _gwLastScene := ""
var _gwSig := ""

func _gwInit() -> void:
	_gwWeb = OS.has_feature("web")
	if not _gwWeb:
		return
	var q := str(JavaScriptBridge.eval("window.location.search", true))
	_gwStartRun = q.contains("start=run")
	if _gwStartRun and FileAccess.file_exists("user://pigeonAscentDb.db"):
		DirAccess.remove_absolute("user://pigeonAscentDb.db")

func _gwPigeon(p:PigeonClass) -> Dictionary:
	return {
		"name": p.strPigeonName, "class": p.resPigeonClass.strClassName, "level": p.iLevel,
		"hp": p.iHp, "max_hp": p.iMaxHp, "food": p.iEnergy, "max_food": p.iMaxEnergy,
		"str": p.iStr, "def": p.iDef, "spd": p.iSpd, "gold": p.iGold,
	}

func _gwTick(delta:float) -> void:
	if not _gwWeb:
		return
	var cs := get_tree().current_scene
	var sceneName := cs.scene_file_path.get_file().get_basename() if cs else ""
	if _gwStartRun and not _gwStarted and sceneName == "intro":
		var btn = cs.find_child("texBtnStartGame", true, false)
		if btn and btn.is_inside_tree():
			_gwStarted = true
			btn.startGame()
			return
	if sceneName != _gwLastScene:
		if sceneName == "root":
			_gwRunsStarted += 1
		_gwLastScene = sceneName
	if sceneName == "root":
		_gwMaxLevel = max(_gwMaxLevel, level)

	var battle = null
	var opponentsOpen := false
	for c in get_tree().root.get_children():
		if c.scene_file_path == _GW_BATTLE and not c.is_queued_for_deletion():
			battle = c
		elif c.scene_file_path == _GW_OPPONENTS and not c.is_queued_for_deletion():
			opponentsOpen = true
	var evolving := false
	if cs:
		for c in cs.get_children():
			if c.scene_file_path == _GW_EVOLVE:
				evolving = true
	var battleEnded:bool = battle != null and battle.ended
	var sig := "%s|%d|%s|%s|%d|%s|%d|%d" % [sceneName, level, battle != null, battleEnded, player.arrEvolutions.size(), evolving, player.iHp, enemy.iHp]
	_gwT += delta
	if _gwT < 0.1 and sig == _gwSig:
		return
	_gwT = 0.0
	_gwSig = sig

	var offered := []
	if opponentsOpen:
		for e in arrEnemyPigeons:
			offered.append(_gwPigeon(e))
	var d := {
		"scene": sceneName, "start_run": _gwStartRun, "runs_started": _gwRunsStarted,
		"ticks_ms": Time.get_ticks_msec(), "level": level, "max_level": _gwMaxLevel,
		"lives": iPlayerLives, "death_handicap": iDeathHandicap,
		"player": _gwPigeon(player), "stat_points": player.iStatPointsLeft,
		"extra_str": player.iExtraStr, "extra_def": player.iExtraDef, "extra_spd": player.iExtraSpd,
		"evolutions": player.arrEvolutions, "bought_items": player.arrBoughtItems,
		"has_wings": hasWings, "has_ice": hasIce, "has_sword": hasSword,
		"opponents_open": opponentsOpen, "opponents": offered, "evolving": evolving,
		"in_battle": battle != null, "battle_fighting": battle != null and battle.fighting,
		"battle_ended": battleEnded, "battle_turn": battle.turn if battle != null else 0,
		"battle_game_over": battleEnded and battle.resetButton.visible,
		"enemy": _gwPigeon(enemy),
	}
	JavaScriptBridge.eval("window.__pigeonHook && window.__pigeonHook(" + JSON.stringify(d) + ");", true)
